use maxt_bindings_common::schema::{
    ApiType, Argument, Operation, Provider, ProviderMethodKind, ProviderOptionValue, Schema, Type,
};

pub(crate) fn render(schema: &Schema) -> String {
    format!(
        "# Generated by `cargo run -p maxt-bindings-codegen`. Do not edit.\n\nEXCHANGES = ({},)\nFEATURES = ({},)\nERROR_VARIANTS = ({},)\nADAPTER_OPERATIONS = ({},)\nCLIENT_MEMBERS = ({},)\nPROVIDER_METHODS = {{\n{}}}\n",
        items(&schema.exchanges),
        items(&schema.features),
        items(schema.errors),
        items(
            &schema
                .adapter_operations
                .iter()
                .map(|value| value.rust_name)
                .collect::<Vec<_>>()
        ),
        owned_items(schema.client_members.iter().map(|value| snake_case(value))),
        schema
            .providers
            .iter()
            .map(render_provider)
            .collect::<String>(),
    )
}

pub(crate) fn render_identifiers(schema: &Schema) -> String {
    let mut output = String::from(
        r#"# Generated by `cargo run -p maxt-bindings-codegen`. Do not edit.

from __future__ import annotations

from calendar import monthrange
from datetime import datetime, timedelta, timezone
from enum import Enum
from typing import Optional

_I64_MIN = -(1 << 63)
_I64_MAX = (1 << 63) - 1
_UNIX_EPOCH = datetime(1970, 1, 1, tzinfo=timezone.utc)


def _is_i64(value: int) -> bool:
    return _I64_MIN <= value <= _I64_MAX
"#,
    );

    for identifier in schema.identifiers {
        output.push_str(&format!("\n\nclass {}(str, Enum):\n", identifier.name));
        for variant in identifier.variants {
            output.push_str(&format!(
                "    {} = \"{}\"\n",
                snake_case(variant.rust_name).to_ascii_uppercase(),
                variant.wire_name,
            ));
        }
        output.push_str(identifier_helpers(identifier.name));
        if identifier.open {
            output.push_str(&format!(
                r#"
    @classmethod
    def other(cls, value: str) -> {}:
        return cls(value)

    @classmethod
    def _missing_(cls, value: object) -> {}:
"#,
                identifier.name, identifier.name,
            ));
            output.push_str(
                r#"        if not isinstance(value, str):
            raise ValueError(value)
        member = str.__new__(cls, value)
        member._name_ = "OTHER"
        member._value_ = value
        cls._value2member_map_[value] = member
        return member
"#,
            );
        }
    }

    for identifier in schema.identifiers {
        let module = if identifier.name == "ExchangeErrorKind" {
            "maxt._api"
        } else {
            "maxt.models"
        };
        output.push_str(&format!(
            "\n{}.__module__ = \"{}\"",
            identifier.name, module
        ));
    }
    output.push_str("\n\n__all__ = [\n");
    for identifier in schema.identifiers {
        output.push_str(&format!("    \"{}\",\n", identifier.name));
    }
    output.push_str("]\n");
    output
}

pub(crate) fn render_api(schema: &Schema) -> String {
    let mut output = String::from(
        r#"# Generated by `cargo run -p maxt-bindings-codegen`. Do not edit.

from __future__ import annotations

from typing import Optional, Union

from ._api import AccountStream, MarketStream, StreamError, StreamEvent
from .models import *  # noqa: F403


class _GeneratedAdapterApi:
    def _unsupported(self, feature: Feature) -> Exception:
        raise NotImplementedError
"#,
    );
    for operation in schema.adapter_operations {
        output.push_str(&render_adapter_method(operation));
    }
    output.push_str(
        r#"

class _GeneratedClientApi:
    _delegate: _GeneratedAdapterApi
"#,
    );
    for operation in schema.adapter_operations {
        for method in operation.client_methods {
            output.push_str(&render_client_method(operation, method));
        }
    }
    output.push_str("\n\n__all__ = [\"_GeneratedAdapterApi\", \"_GeneratedClientApi\"]\n");
    output
}

pub(crate) fn render_native_stub(schema: &Schema) -> String {
    let mut output = String::from(
        r#"# Generated by `cargo run -p maxt-bindings-codegen`. Do not edit.

from __future__ import annotations

from typing import Any, AsyncIterator, Awaitable, Optional

Wire = dict[str, Any]


class MaxtError(Exception):
    kind: str
    wire: Wire


class NativeMarketStream(AsyncIterator[Wire]):
    def __aiter__(self) -> NativeMarketStream: ...
    def __anext__(self) -> Awaitable[Wire]: ...
    def aclose(self) -> Awaitable[None]: ...


class NativeAccountStream(AsyncIterator[Wire]):
    def __aiter__(self) -> NativeAccountStream: ...
    def __anext__(self) -> Awaitable[Wire]: ...
    def aclose(self) -> Awaitable[None]: ...


class NativeClient:
    @staticmethod
    def from_adapter(adapter: Any) -> NativeClient: ...

    @property
    def exchange(self) -> str: ...

    def supports(self, feature: Any) -> bool: ...
"#,
    );
    for operation in schema.adapter_operations {
        for method in operation.client_methods {
            output.push_str(&format!(
                "    def {}(self{}) -> Awaitable[{}]: ...\n",
                snake_case(method.name),
                native_client_arguments(operation, method),
                native_type(operation.result),
            ));
        }
    }
    for provider in schema.providers {
        output.push_str(&render_native_provider(provider));
    }
    output
}

fn render_rust_errors(schema: &Schema) -> String {
    let error = schema
        .unions
        .iter()
        .find(|union| union.name == "ErrorWire")
        .expect("missing ErrorWire union");
    let mut kind_arms = String::new();
    let mut wire_arms = String::new();
    for variant in &error.variants {
        let rust_variant = pascal_case(variant.name);
        kind_arms.push_str(&format!(
            "        maxt::Error::{rust_variant} {{ .. }} => \"{}\",\n",
            variant.name
        ));
        let arm = match variant.name {
            "invalid_request" => {
                "maxt::Error::InvalidRequest { field, detail } => wire_dict!(py, \"kind\" => \"invalid_request\", \"message\" => &message, \"retryable\" => retryable, \"field\" => field, \"detail\" => detail),"
            }
            "unsupported" => {
                "maxt::Error::Unsupported { feature, exchange, detail } => wire_dict!(py, \"kind\" => \"unsupported\", \"message\" => &message, \"retryable\" => retryable, \"feature\" => feature_to_wire(*feature)?, \"exchange\" => exchange, \"detail\" => detail),"
            }
            "adapter" => {
                "maxt::Error::Adapter { detail } => wire_dict!(py, \"kind\" => \"adapter\", \"message\" => &message, \"retryable\" => retryable, \"detail\" => detail),"
            }
            "auth" => {
                "maxt::Error::Auth { detail } => wire_dict!(py, \"kind\" => \"auth\", \"message\" => &message, \"retryable\" => retryable, \"detail\" => detail),"
            }
            "exchange" => {
                "maxt::Error::Exchange { exchange, code, message: provider_message, status, kind } => wire_dict!(py, \"kind\" => \"exchange\", \"message\" => &message, \"retryable\" => retryable, \"exchange\" => exchange, \"code\" => code, \"provider_message\" => provider_message, \"status\" => status, \"exchange_kind\" => exchange_error_kind_to_wire(*kind)?),"
            }
            "transport" => {
                "maxt::Error::Transport { detail } => wire_dict!(py, \"kind\" => \"transport\", \"message\" => &message, \"retryable\" => retryable, \"detail\" => detail),"
            }
            "decode" => {
                "maxt::Error::Decode { detail } => wire_dict!(py, \"kind\" => \"decode\", \"message\" => &message, \"retryable\" => retryable, \"detail\" => detail),"
            }
            name => panic!("unsupported ErrorWire variant: {name}"),
        };
        wire_arms.push_str("        ");
        wire_arms.push_str(arm);
        wire_arms.push('\n');
    }
    format!(
        "pub(crate) fn error_kind(error: &maxt::Error) -> &'static str {{\n    match error {{\n{kind_arms}        _ => \"binding_contract\",\n    }}\n}}\n\npub(crate) fn error_to_wire(py: Python<'_>, error: &maxt::Error) -> PyResult<Py<PyAny>> {{\n    let message = error.to_string();\n    let retryable = error.is_retryable();\n    match error {{\n{wire_arms}        _ => wire_dict!(py, \"kind\" => \"binding_contract\", \"message\" => \"maxt binding contract does not map a new Error variant\", \"retryable\" => false),\n    }}\n}}\n\n"
    )
}

pub(crate) fn render_native_delegate(schema: &Schema) -> String {
    let mut output = String::from(
        r#"# Generated by `cargo run -p maxt-bindings-codegen`. Do not edit.

from __future__ import annotations

from typing import Any, Awaitable, Callable, Optional, TypeVar, Union

from ._api import AccountStream, InvalidRequestError, MarketStream, StreamError, StreamEvent
from .models import *  # noqa: F403
from .models import _model_from_wire

T = TypeVar("T")


class _GeneratedNativeClientDelegateApi:
    _client: Any
    _native_module: Any

    async def _call(self, method: Callable[..., Awaitable[T]], *args: Any) -> T:
        raise NotImplementedError

    def _market_stream(self, source: Any) -> MarketStream[Union[StreamEvent[MarketEvent], StreamError]]:
        raise NotImplementedError

    def _account_stream(self, source: Any) -> AccountStream[Union[StreamEvent[AccountEvent], StreamError]]:
        raise NotImplementedError
"#,
    );
    for operation in schema.adapter_operations {
        output.push_str(&render_native_delegate_method(operation));
    }
    output.push_str("\n\n__all__ = [\"_GeneratedNativeClientDelegateApi\"]\n");
    output
}

pub(crate) fn render_wire_schema(schema: &Schema) -> String {
    let mut output = String::from(
        "# Generated by `cargo run -p maxt-bindings-codegen`. Do not edit.\n\nRECORD_FIELDS = {\n",
    );
    for record in &schema.records {
        let name = record.name.strip_suffix("Wire").unwrap_or(record.name);
        output.push_str(&format!("    \"{name}\": {{\n"));
        for field in &record.fields {
            output.push_str(&format!(
                "        \"{}\": \"{}\",\n",
                field.name,
                python_wire_type(&field.ty)
            ));
        }
        output.push_str("    },\n");
    }
    output.push_str("}\n\nUNION_FIELDS = {\n");
    for union in &schema.unions {
        let name = union.name.strip_suffix("Wire").unwrap_or(union.name);
        output.push_str(&format!("    \"{name}\": {{\n"));
        for variant in &union.variants {
            output.push_str(&format!("        \"{}\": {{\n", variant.name));
            for field in &variant.fields {
                output.push_str(&format!(
                    "            \"{}\": \"{}\",\n",
                    field.name,
                    python_wire_type(&field.ty)
                ));
            }
            output.push_str("        },\n");
        }
        output.push_str("    },\n");
    }
    output.push_str("}\n\nIDENTIFIER_VARIANTS = {\n");
    for identifier in schema.identifiers {
        output.push_str(&format!(
            "    \"{}\": ({},),\n",
            identifier.name,
            identifier
                .variants
                .iter()
                .map(|variant| format!("\"{}\"", variant.wire_name))
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }
    output.push_str(
        "}\n\nERROR_FIELDS = UNION_FIELDS[\"Error\"]\n\n__all__ = [\n    \"ERROR_FIELDS\",\n    \"IDENTIFIER_VARIANTS\",\n    \"RECORD_FIELDS\",\n    \"UNION_FIELDS\",\n]\n",
    );
    output
}

fn python_wire_type(value: &Type) -> String {
    match value {
        Type::String => "string".to_owned(),
        Type::Boolean => "boolean".to_owned(),
        Type::Number => "number".to_owned(),
        Type::UnsignedInteger => "unsigned_integer".to_owned(),
        Type::Decimal => "decimal".to_owned(),
        Type::Timestamp => "timestamp".to_owned(),
        Type::Identifier(name) => format!("identifier:{name}"),
        Type::Named(name) => format!("named:{}", name.strip_suffix("Wire").unwrap_or(name)),
        Type::Optional(inner) => format!("optional:{}", python_wire_type(inner)),
        Type::List(inner) => format!("list:{}", python_wire_type(inner)),
        Type::Tuple(values) => format!(
            "tuple:{}",
            values
                .iter()
                .map(python_wire_type)
                .collect::<Vec<_>>()
                .join(",")
        ),
    }
}

fn render_native_delegate_method(operation: &Operation) -> String {
    let name = snake_case(operation.rust_name);
    let arguments = python_arguments(operation.arguments, false);
    let values = operation
        .arguments
        .iter()
        .map(|argument| python_name(argument.name))
        .collect::<Vec<_>>();
    let call = match operation.rust_name {
        "open_orders" | "positions" => {
            let market = &values[0];
            format!(
                "method = self._client.{name} if {market} is None else self._client.{name}_on\n        value = await self._call(method, *(() if {market} is None else ({market},)))"
            )
        }
        _ => format!(
            "value = await self._call(self._client.{name}{})",
            if values.is_empty() {
                String::new()
            } else {
                format!(", {}", values.join(", "))
            }
        ),
    };
    let result = python_type(operation.result);
    let validation = if operation.rust_name == "subscribe" {
        "        if not subscription.markets:\n            raise InvalidRequestError(\"markets\", \"a subscription needs at least one market\")\n        if not subscription.feeds:\n            raise InvalidRequestError(\"feeds\", \"a subscription needs at least one feed\")\n"
    } else {
        ""
    };
    let return_value = match operation.result {
        ApiType::List(model) => {
            format!("return [_model_from_wire(\"{model}\", item) for item in value]")
        }
        ApiType::Named(model) => format!("return _model_from_wire(\"{model}\", value)"),
        ApiType::Page(model) => {
            format!("return _model_from_wire(\"{model}Page\", value)")
        }
        ApiType::MarketStream => "return self._market_stream(value)".to_owned(),
        ApiType::AccountStream => "return self._account_stream(value)".to_owned(),
        ApiType::Unit => "return None".to_owned(),
        _ => panic!("unsupported native delegate result: {:?}", operation.result),
    };
    if operation.result == ApiType::Unit {
        let call = call.replacen("value = await", "await", 1);
        return format!(
            "\n    async def {name}(self{arguments}) -> {result}:\n{validation}        {call}\n        {return_value}\n"
        );
    }
    format!(
        "\n    async def {name}(self{arguments}) -> {result}:\n{validation}        {call}\n        {return_value}\n"
    )
}

pub(crate) fn render_rust_client(schema: &Schema) -> String {
    let mut output = String::from(
        "// Generated by `cargo run -p maxt-bindings-codegen`. Do not edit.\n\n\
         #[pymethods]\n\
         impl NativeClient {\n",
    );
    for operation in schema.adapter_operations {
        for method in operation.client_methods {
            output.push_str(&render_rust_client_method(operation, method));
        }
    }
    output.push_str("}\n");
    output
}

pub(crate) fn render_rust_dispatcher(schema: &Schema) -> String {
    let mut output = String::from(
        "// Generated by `cargo run -p maxt-bindings-codegen`. Do not edit.\n\n\
         #[derive(Clone, Copy)]\n\
         enum ReplyKind {\n",
    );
    for operation in schema.adapter_operations {
        output.push_str(&format!(
            "    {},\n",
            rust_reply_kind(operation.rust_name, operation.result)
        ));
    }
    output.push_str(
        r#"}

fn prepare_call(
    py: Python<'_>,
    object: &Py<PyAny>,
    call: AdapterCall,
) -> PyResult<(ReplyKind, PythonFuture)> {
    let (method, args, reply) = match call {
"#,
    );
    for operation in schema.adapter_operations {
        output.push_str(&render_dispatch_arm(operation));
    }
    output.push_str(
        r#"        _ => {
            return Err(pyo3::exceptions::PyValueError::new_err(
                "unknown adapter call",
            ));
        }
    };
    let args = PyTuple::new(py, args)?;
    let awaitable = object.bind(py).call_method(method, args, None)?;
    let future = pyo3_async_runtimes::tokio::into_future(awaitable)?;
    Ok((reply, Box::pin(future)))
}
"#,
    );
    output
}

pub(crate) fn render_rust_convert(schema: &Schema) -> String {
    let mut output =
        String::from("// Generated by `cargo run -p maxt-bindings-codegen`. Do not edit.\n\n");
    for name in [
        "Exchange",
        "Feature",
        "MarketKind",
        "Interval",
        "Side",
        "OrderType",
        "TimeInForce",
        "MarginMode",
        "MarketStatus",
        "OrderStatus",
        "Overflow",
        "ExchangeErrorKind",
    ] {
        let identifier = schema
            .identifier(name)
            .unwrap_or_else(|| panic!("missing identifier {name}"));
        output.push_str(&render_rust_identifier(identifier));
    }
    for name in [
        "Market",
        "MarketInfo",
        "Trade",
        "Level",
        "OrderBook",
        "Ticker",
        "Candle",
        "Balance",
        "Order",
        "Position",
        "MarginSummary",
        "FundingRate",
        "FundingPayment",
    ] {
        let record = schema
            .records
            .iter()
            .find(|record| record.name == format!("{name}Wire"))
            .unwrap_or_else(|| panic!("missing record {name}Wire"));
        output.push_str(&render_rust_record(name, &record.fields));
    }
    for operation in schema.adapter_operations {
        if let ApiType::Page(name) = operation.result {
            output.push_str(&format!(
                "pub(crate) fn {}_page_to_wire(\n    py: Python<'_>,\n    value: &Page<{name}>,\n) -> PyResult<Py<PyAny>> {{\n    wire_dict!(\n        py,\n        \"items\" => list_to_wire(py, &value.items, {}_to_wire)?,\n        \"next\" => value.next.as_ref().map(Cursor::as_str),\n    )\n}}\n\n",
                operation.rust_name,
                snake_case(name)
            ));
        }
    }
    output.push_str(&render_rust_errors(schema));
    output.truncate(output.trim_end().len());
    output.push('\n');
    output
}

pub(crate) fn render_rust_provider_convert(schema: &Schema) -> String {
    let mut output =
        String::from("// Generated by `cargo run -p maxt-bindings-codegen`. Do not edit.\n\n");
    output.push_str(&render_provider_identifier_to_wire(
        schema,
        "BithumbAlertStep",
        false,
    ));
    output.push_str(&render_provider_identifier_to_wire(
        schema,
        "HyperliquidLedgerKind",
        true,
    ));
    for name in [
        "BinanceSymbolFilters",
        "BinanceSpotOrderDetail",
        "HyperliquidLedgerEntry",
        "HyperliquidAssetContext",
    ] {
        let record = schema
            .records
            .iter()
            .find(|record| record.name == format!("{name}Wire"))
            .unwrap_or_else(|| panic!("missing provider record {name}Wire"));
        output.push_str(&render_rust_provider_record(name, &record.fields));
    }
    output.push_str(
        "fn upbit_market_event_to_wire(\n    py: Python<'_>,\n    value: &(Market, UpbitMarketEvent),\n) -> PyResult<Py<PyAny>> {\n    provider_dict!(\n        py,\n        \"market\" => market_to_wire(py, &value.0)?,\n        \"warning\" => value.1.warning,\n        \"cautions\" => &value.1.cautions,\n    )\n}\n\n\
         fn bithumb_market_warning_to_wire(\n    py: Python<'_>,\n    value: &(Market, String),\n) -> PyResult<Py<PyAny>> {\n    provider_dict!(\n        py,\n        \"market\" => market_to_wire(py, &value.0)?,\n        \"warning\" => &value.1,\n    )\n}\n\n\
         fn bithumb_market_alert_to_wire(\n    py: Python<'_>,\n    value: &(Market, BithumbMarketAlert),\n) -> PyResult<Py<PyAny>> {\n    provider_dict!(\n        py,\n        \"market\" => market_to_wire(py, &value.0)?,\n        \"kind\" => &value.1.kind,\n        \"step\" => bithumb_alert_step_to_wire(value.1.step)?,\n        \"ends_at\" => timestamp_to_wire(value.1.ends_at),\n    )\n}\n\n\
         fn hyperliquid_ledger_page_to_wire(\n    py: Python<'_>,\n    value: &Page<HyperliquidLedgerEntry>,\n) -> PyResult<Py<PyAny>> {\n    provider_dict!(\n        py,\n        \"items\" => list_to_wire(py, &value.items, hyperliquid_ledger_entry_to_wire)?,\n        \"next\" => value.next.as_ref().map(Cursor::as_str),\n    )\n}\n",
    );
    output
}

fn render_rust_provider_record(
    name: &str,
    fields: &[maxt_bindings_common::schema::Field],
) -> String {
    let function = if name == "BinanceSpotOrderDetail" {
        "binance_spot_order".to_owned()
    } else {
        snake_case(name)
    };
    let values = fields
        .iter()
        .map(|field| {
            let value = if name == "HyperliquidLedgerEntry" && field.name == "kind" {
                "hyperliquid_ledger_kind_to_wire(&value.kind)?".to_owned()
            } else {
                rust_record_field(field.name, &field.ty)
            };
            format!("        \"{}\" => {},\n", field.name, value)
        })
        .collect::<String>();
    format!(
        "fn {function}_to_wire(\n    py: Python<'_>,\n    value: &maxt::adapters::{name},\n) -> PyResult<Py<PyAny>> {{\n    provider_dict!(\n        py,\n{values}    )\n}}\n\n"
    )
}

fn render_provider_identifier_to_wire(schema: &Schema, name: &str, open: bool) -> String {
    let identifier = schema
        .identifier(name)
        .unwrap_or_else(|| panic!("missing provider identifier {name}"));
    let function = snake_case(name);
    let arms = identifier
        .variants
        .iter()
        .map(|variant| {
            format!(
                "        {name}::{} => Ok(\"{}\"),\n",
                variant.rust_name, variant.wire_name
            )
        })
        .collect::<String>();
    let other = if open {
        format!("        {name}::Other(value) => Ok(value),\n")
    } else {
        String::new()
    };
    let argument = if open {
        format!("&{name}")
    } else {
        name.to_owned()
    };
    let result = if open { "&str" } else { "&'static str" };
    format!(
        "fn {function}_to_wire(value: {argument}) -> PyResult<{result}> {{\n    match value {{\n{arms}{other}        _ => Err(PyValueError::new_err(\"maxt binding contract does not map a new {name} variant\")),\n    }}\n}}\n\n"
    )
}

fn render_rust_identifier(identifier: &maxt_bindings_common::schema::Identifier) -> String {
    let function = snake_case(identifier.name);
    let rust_type = if matches!(
        identifier.name,
        "UpbitRegion" | "BithumbAlertStep" | "BinanceMarket" | "HyperliquidLedgerKind"
    ) {
        format!("maxt::adapters::{}", identifier.name)
    } else {
        format!("maxt::{}", identifier.name)
    };
    let from_arms = identifier
        .variants
        .iter()
        .map(|variant| {
            format!(
                "        \"{}\" => Ok({rust_type}::{}),\n",
                variant.wire_name, variant.rust_name
            )
        })
        .collect::<String>();
    let to_arms = identifier
        .variants
        .iter()
        .map(|variant| {
            format!(
                "        {rust_type}::{} => Ok(\"{}\"),\n",
                variant.rust_name, variant.wire_name
            )
        })
        .collect::<String>();
    let unknown_from = if identifier.open {
        format!("        value => Ok({rust_type}::Other(value.to_owned())),\n")
    } else {
        format!(
            "        _ => Err(invalid(\"{}\", &value)),\n",
            function.replace('_', " ")
        )
    };
    let unknown_to = if identifier.open {
        format!(
            "        {rust_type}::Other(value) => Ok(value.as_str()),\n        _ => Err(binding_contract(\"{}\")),\n",
            identifier.name
        )
    } else {
        format!(
            "        _ => Err(binding_contract(\"{}\")),\n",
            identifier.name
        )
    };
    format!(
        "pub(crate) fn {function}_from_wire(value: &Bound<'_, PyAny>) -> PyResult<{rust_type}> {{\n    let value = text(value)?;\n    match value.as_str() {{\n{from_arms}{unknown_from}    }}\n}}\n\npub(crate) fn {function}_to_wire(value: {rust_type}) -> PyResult<&'static str> {{\n    match value {{\n{to_arms}{unknown_to}    }}\n}}\n\n"
    )
}

fn render_rust_record(name: &str, fields: &[maxt_bindings_common::schema::Field]) -> String {
    let function = snake_case(name);
    let values = fields
        .iter()
        .map(|field| {
            format!(
                "        \"{}\" => {},\n",
                field.name,
                rust_record_field(field.name, &field.ty)
            )
        })
        .collect::<String>();
    format!(
        "pub(crate) fn {function}_to_wire(\n    py: Python<'_>,\n    value: &maxt::{name},\n) -> PyResult<Py<PyAny>> {{\n    wire_dict!(\n        py,\n{values}    )\n}}\n\n"
    )
}

fn rust_record_field(name: &str, ty: &Type) -> String {
    let field = format!("value.{name}");
    match ty {
        Type::String => format!("&{field}"),
        Type::Boolean | Type::Number | Type::UnsignedInteger => field,
        Type::Decimal => format!("decimal_to_wire({field})"),
        Type::Timestamp => format!("timestamp_to_wire({field})"),
        Type::Identifier(identifier) => {
            format!("{}_to_wire({field})?", snake_case(identifier))
        }
        Type::Named(named) if named == &"MarketKindWire" => {
            format!("market_kind_to_wire({field})?")
        }
        Type::Named(named) => format!(
            "{}_to_wire(py, &{field})?",
            snake_case(named.strip_suffix("Wire").unwrap_or(named))
        ),
        Type::Optional(inner) => match inner.as_ref() {
            Type::String => format!("&{field}"),
            Type::Boolean | Type::Number | Type::UnsignedInteger => field,
            Type::Decimal => format!("{field}.map(decimal_to_wire)"),
            Type::Timestamp => format!("{field}.map(timestamp_to_wire)"),
            Type::Identifier(identifier) => format!(
                "{field}.map({}_to_wire).transpose()?",
                snake_case(identifier)
            ),
            Type::Named(named) => format!(
                "{field}.as_ref().map(|item| {}_to_wire(py, item)).transpose()?",
                snake_case(named.strip_suffix("Wire").unwrap_or(named))
            ),
            other => panic!("unsupported optional record field: {other:?}"),
        },
        Type::List(inner) => match inner.as_ref() {
            Type::Named(named) => format!(
                "list_to_wire(py, &{field}, {}_to_wire)?",
                snake_case(named.strip_suffix("Wire").unwrap_or(named))
            ),
            other => panic!("unsupported list record field: {other:?}"),
        },
        Type::Tuple(_) => panic!("tuple record fields are not used by Python core DTOs"),
    }
}

fn render_dispatch_arm(operation: &Operation) -> String {
    let variant = pascal_case(operation.rust_name);
    let fields = operation
        .arguments
        .iter()
        .map(|argument| snake_case(argument.name))
        .collect::<Vec<_>>();
    let pattern = if fields.is_empty() {
        format!("AdapterCall::{variant}")
    } else {
        format!("AdapterCall::{variant} {{ {} }}", fields.join(", "))
    };
    let arguments = operation
        .arguments
        .iter()
        .map(|argument| rust_dispatch_argument(*argument))
        .collect::<Vec<_>>();
    if arguments.is_empty() {
        return format!(
            "        {pattern} => (\"{}\", vec![], ReplyKind::{}),\n",
            operation.rust_name,
            rust_reply_kind(operation.rust_name, operation.result)
        );
    }
    let arguments = if operation.arguments.len() == 1 {
        format!("vec![{}]", arguments[0])
    } else {
        format!(
            "vec![\n                {},\n            ]",
            arguments.join(",\n                ")
        )
    };
    format!(
        "        {pattern} => (\n            \"{}\",\n            {arguments},\n            ReplyKind::{},\n        ),\n",
        operation.rust_name,
        rust_reply_kind(operation.rust_name, operation.result)
    )
}

fn rust_dispatch_argument(argument: Argument) -> String {
    let name = snake_case(argument.name);
    match argument.ty {
        ApiType::Named("MarketKind") => {
            format!("enum_object(py, \"MarketKind\", market_kind_to_wire({name})?)?")
        }
        ApiType::Named("Market") => format!("market_object(py, &{name})?"),
        ApiType::OptionalNamed("Market") => {
            format!("optional_market_object(py, {name}.as_ref())?")
        }
        ApiType::Named(type_name) => {
            format!("{}_object(py, &{name})?", snake_case(type_name))
        }
        ApiType::String | ApiType::OptionalNumber => format!("{name}.into_py_any(py)?"),
        _ => panic!("unsupported Python dispatcher argument: {:?}", argument.ty),
    }
}

fn rust_reply_kind(operation: &str, result: ApiType) -> String {
    match result {
        ApiType::MarketStream => "MarketStream".to_owned(),
        ApiType::AccountStream => "AccountStream".to_owned(),
        ApiType::Unit => "Unit".to_owned(),
        _ => pascal_case(operation),
    }
}

fn pascal_case(value: &str) -> String {
    value
        .split('_')
        .map(|part| {
            let mut characters = part.chars();
            characters
                .next()
                .map(|first| first.to_ascii_uppercase().to_string() + characters.as_str())
                .unwrap_or_default()
        })
        .collect()
}

fn render_rust_client_method(
    operation: &Operation,
    method: &maxt_bindings_common::schema::ClientMethod,
) -> String {
    let name = snake_case(method.name);
    let arguments = match method.name {
        "subscribe" | "subscribeAccount" => operation.arguments,
        _ => method.arguments,
    };
    if method.name == "subscribeWith" {
        return rust_alias_method(&name, arguments, "self.subscribe(py, subscription, config)");
    }
    if method.name == "subscribeAccountWith" {
        return rust_alias_method(&name, arguments, "self.subscribe_account(py, config)");
    }

    let mut output = String::new();
    let defaults = arguments
        .iter()
        .filter_map(|argument| {
            argument
                .default
                .map(|_| format!("{}=None", snake_case(argument.name)))
        })
        .collect::<Vec<_>>();
    if !defaults.is_empty() {
        let signature = arguments
            .iter()
            .map(|argument| {
                let name = snake_case(argument.name);
                if argument.default.is_some() {
                    format!("{name}=None")
                } else {
                    name
                }
            })
            .collect::<Vec<_>>()
            .join(", ");
        output.push_str(&format!("    #[pyo3(signature = ({signature}))]\n"));
    }
    output.push_str(&format!(
        "    fn {name}<'py>(\n        &self,\n        py: Python<'py>,"
    ));
    for argument in arguments {
        output.push_str(&format!(
            "\n        {}: {},",
            snake_case(argument.name),
            rust_python_argument_type(argument.ty)
        ));
    }
    output.push_str("\n    ) -> PyResult<Bound<'py, PyAny>> {\n");
    for argument in arguments {
        if let Some(conversion) = rust_input_conversion(*argument) {
            output.push_str(&format!("        {conversion}\n"));
        }
    }
    output.push_str("        let core = self.core();\n");
    let core_method = match method.name {
        "subscribe" => "subscribe_with",
        "subscribeAccount" => "subscribe_account_with",
        _ => method.native_name,
    };
    let call_arguments = arguments
        .iter()
        .map(|argument| rust_core_argument(*argument))
        .collect::<Vec<_>>()
        .join(", ");
    let call_arguments = if call_arguments.is_empty() {
        String::new()
    } else {
        call_arguments
    };
    output.push_str("        operation(\n            py,\n");
    output.push_str(&format!(
        "            async move {{ core.{}({call_arguments}).await }},\n",
        snake_case(core_method)
    ));
    output.push_str(&format!(
        "            {},\n        )\n    }}\n\n",
        rust_output_conversion(operation.result)
    ));
    output
}

fn rust_alias_method(name: &str, arguments: &[Argument], call: &str) -> String {
    let mut output = format!("    fn {name}<'py>(\n        &self,\n        py: Python<'py>,");
    for argument in arguments {
        output.push_str(&format!(
            "\n        {}: {},",
            snake_case(argument.name),
            rust_python_argument_type(argument.ty)
        ));
    }
    output.push_str(&format!(
        "\n    ) -> PyResult<Bound<'py, PyAny>> {{\n        {call}\n    }}\n\n"
    ));
    output
}

fn rust_python_argument_type(value: ApiType) -> String {
    match value {
        ApiType::String => "String".to_owned(),
        ApiType::Number => "u32".to_owned(),
        ApiType::OptionalString => "Option<String>".to_owned(),
        ApiType::OptionalNumber => "Option<u32>".to_owned(),
        ApiType::Named(_) => "&Bound<'_, PyAny>".to_owned(),
        ApiType::OptionalNamed(_) => "Option<&Bound<'_, PyAny>>".to_owned(),
        _ => panic!("unsupported NativeClient argument type: {value:?}"),
    }
}

fn rust_input_conversion(argument: Argument) -> Option<String> {
    let name = snake_case(argument.name);
    match argument.ty {
        ApiType::Named(type_name) => Some(format!(
            "let {name} = {}_from_wire({name})?;",
            snake_case(type_name)
        )),
        _ => None,
    }
}

fn rust_core_argument(argument: Argument) -> String {
    let name = snake_case(argument.name);
    match argument.ty {
        ApiType::Named("MarketKind") => name,
        ApiType::Named(_) | ApiType::String => format!("&{name}"),
        _ => name,
    }
}

fn rust_output_conversion(value: ApiType) -> String {
    match value {
        ApiType::List(name) => format!(
            "|py, values| list_to_wire(py, &values, {}_to_wire)",
            snake_case(name)
        ),
        ApiType::Named(name) => {
            format!("|py, value| {}_to_wire(py, &value)", snake_case(name))
        }
        ApiType::Page("FundingRate") => {
            "|py, value| funding_rates_page_to_wire(py, &value)".to_owned()
        }
        ApiType::Page("FundingPayment") => {
            "|py, value| funding_payments_page_to_wire(py, &value)".to_owned()
        }
        ApiType::MarketStream => {
            "|py, value| Ok(crate::stream::market_stream(py, value)?.unbind())".to_owned()
        }
        ApiType::AccountStream => {
            "|py, value| Ok(crate::stream::account_stream(py, value)?.unbind())".to_owned()
        }
        ApiType::Unit => "|py, ()| Ok(py.None())".to_owned(),
        _ => panic!("unsupported NativeClient result type: {value:?}"),
    }
}

fn render_native_provider(provider: &Provider) -> String {
    let class_name = format!("Native{}", provider.adapter);
    let mut arguments = Vec::<(&str, ApiType)>::new();
    for constructor in provider.constructors {
        for option in constructor.options {
            if arguments.iter().any(|(name, _)| *name == option.name) {
                continue;
            }
            let ty = match option.value {
                ProviderOptionValue::Argument(argument_name) => {
                    constructor
                        .arguments
                        .iter()
                        .find(|argument| argument.name == argument_name)
                        .expect("provider option argument must exist")
                        .ty
                }
                ProviderOptionValue::Identifier { .. } => ApiType::String,
                ProviderOptionValue::Boolean(_) => ApiType::Boolean,
            };
            arguments.push((option.name, ty));
        }
    }
    let constructor = arguments
        .iter()
        .map(|(name, ty)| format!(", {name}: {} = ...", native_argument_type(*ty)))
        .collect::<String>();
    let mut output = format!(
        "\n\nclass {class_name}:\n    def __init__(self, *{constructor}) -> None: ...\n\n    @property\n    def authenticated(self) -> bool: ...\n\n    def client(self) -> NativeClient: ...\n"
    );
    for method in provider.methods {
        let name = snake_case(method.rust_name);
        match method.kind {
            ProviderMethodKind::Property => output.push_str(&format!(
                "\n    @property\n    def {name}(self) -> {result}: ...\n",
                result = native_property_type(method.result)
            )),
            ProviderMethodKind::Async => output.push_str(&format!(
                "    def {name}(self{}) -> Awaitable[{result}]: ...\n",
                native_provider_arguments(provider.exchange, method.rust_name, method.arguments),
                result = native_type(method.result),
            )),
        }
    }
    if provider.exchange == "binance" {
        output.push_str(
            "\n\nclass NativeBinanceListenKey:\n    @property\n    def value(self) -> str: ...\n",
        );
    }
    output
}

fn native_argument_type(value: ApiType) -> String {
    match value {
        ApiType::HandleToken(name) => format!("Native{name}"),
        ApiType::List(_) => "list[Any]".to_owned(),
        ApiType::Named(_) => "Any".to_owned(),
        ApiType::OptionalNamed("Timestamp") => "Optional[int]".to_owned(),
        ApiType::OptionalNamed("Cursor") => "Optional[str]".to_owned(),
        ApiType::OptionalNamed(_) => "Optional[Any]".to_owned(),
        _ => python_type(value),
    }
}

fn native_arguments(arguments: &[Argument]) -> String {
    arguments
        .iter()
        .map(|argument| {
            let default = argument.default.map(|_| " = ...").unwrap_or("");
            format!(
                ", {}: {}{}",
                python_name(argument.name),
                native_argument_type(argument.ty),
                default
            )
        })
        .collect()
}

fn native_client_arguments(
    operation: &Operation,
    method: &maxt_bindings_common::schema::ClientMethod,
) -> String {
    match method.name {
        "subscribe" | "subscribeAccount" => native_arguments(operation.arguments),
        _ => native_arguments(method.arguments),
    }
}

fn native_provider_arguments(exchange: &str, method: &str, arguments: &[Argument]) -> String {
    if exchange == "hyperliquid" && method == "non_funding_ledger" {
        return arguments
            .iter()
            .map(|argument| {
                let name = match argument.name {
                    "from" => "from_ns",
                    "to" => "to_ns",
                    name => name,
                };
                let default = argument.default.map(|_| " = ...").unwrap_or("");
                format!(", {name}: {}{default}", native_argument_type(argument.ty))
            })
            .collect();
    }
    native_arguments(arguments)
}

fn native_property_type(value: ApiType) -> String {
    match value {
        ApiType::Named(_) => "str".to_owned(),
        _ => native_type(value),
    }
}

fn native_type(value: ApiType) -> String {
    match value {
        ApiType::List(_) => "list[Wire]".to_owned(),
        ApiType::PairList(_, _) => "list[Wire]".to_owned(),
        ApiType::Named(_) | ApiType::Page(_) => "Wire".to_owned(),
        ApiType::Handle(name) => format!("Native{name}"),
        ApiType::HandleToken(name) => format!("Native{name}"),
        ApiType::MarketStream => "NativeMarketStream".to_owned(),
        ApiType::AccountStream => "NativeAccountStream".to_owned(),
        ApiType::Unit => "None".to_owned(),
        ApiType::Boolean => "bool".to_owned(),
        ApiType::String => "str".to_owned(),
        ApiType::Number => "int".to_owned(),
        ApiType::OptionalString => "Optional[str]".to_owned(),
        ApiType::OptionalNumber => "Optional[int]".to_owned(),
        ApiType::OptionalNamed(_) => "Optional[Any]".to_owned(),
    }
}

fn render_adapter_method(operation: &Operation) -> String {
    let name = snake_case(operation.rust_name);
    let arguments = python_arguments(operation.arguments, false);
    let result = python_type(operation.result);
    let body = if operation.rust_name == "subscribe" {
        "raise NotImplementedError".to_owned()
    } else {
        let feature = snake_case(operation.feature).to_ascii_uppercase();
        format!("raise self._unsupported(Feature.{feature})")
    };
    format!("\n    async def {name}(self{arguments}) -> {result}:\n        {body}\n")
}

fn render_client_method(
    operation: &Operation,
    method: &maxt_bindings_common::schema::ClientMethod,
) -> String {
    let name = snake_case(method.name);
    let arguments = python_arguments(method.arguments, false);
    let values = method
        .arguments
        .iter()
        .map(|argument| python_name(argument.name))
        .collect::<Vec<_>>();
    let call = match method.name {
        "subscribe" => format!("self.subscribe_with({}, StreamConfig())", values[0]),
        "subscribeWith" => format!("self._delegate.subscribe({})", values.join(", ")),
        "openOrders" => "self._delegate.open_orders(None)".to_owned(),
        "openOrdersOn" => format!("self._delegate.open_orders({})", values[0]),
        "subscribeAccount" => "self.subscribe_account_with(StreamConfig())".to_owned(),
        "subscribeAccountWith" => {
            format!("self._delegate.subscribe_account({})", values.join(", "))
        }
        "positions" => "self._delegate.positions(None)".to_owned(),
        "positionsOn" => format!("self._delegate.positions({})", values[0]),
        _ => format!(
            "self._delegate.{}({})",
            snake_case(method.native_name),
            values.join(", ")
        ),
    };
    let result = python_type(operation.result);
    let body = if matches!(method.name, "positions" | "positionsOn") {
        format!("return [row for row in await {call} if not row.is_flat()]")
    } else {
        format!("return await {call}")
    };
    format!("\n    async def {name}(self{arguments}) -> {result}:\n        {body}\n")
}

fn python_arguments(arguments: &[Argument], stub: bool) -> String {
    arguments
        .iter()
        .map(|argument| {
            let default = argument
                .default
                .map(|_| if stub { " = ..." } else { " = None" });
            format!(
                ", {}: {}{}",
                python_name(argument.name),
                python_type(argument.ty),
                default.unwrap_or("")
            )
        })
        .collect()
}

fn python_name(value: &str) -> String {
    let value = snake_case(value);
    if value == "from" {
        "from_".to_owned()
    } else {
        value
    }
}

fn python_type(value: ApiType) -> String {
    match value {
        ApiType::String => "str".to_owned(),
        ApiType::Boolean => "bool".to_owned(),
        ApiType::Number => "int".to_owned(),
        ApiType::Named(name) => python_named_type(name).to_owned(),
        ApiType::OptionalString => "Optional[str]".to_owned(),
        ApiType::OptionalNumber => "Optional[int]".to_owned(),
        ApiType::OptionalNamed(name) => format!("Optional[{}]", python_named_type(name)),
        ApiType::List(name) => format!("list[{}]", python_named_type(name)),
        ApiType::PairList(first, second) => format!(
            "list[tuple[{}, {}]]",
            python_named_type(first),
            python_named_type(second)
        ),
        ApiType::Page(name) => format!("Page[{name}]"),
        ApiType::Handle(name) | ApiType::HandleToken(name) => name.to_owned(),
        ApiType::MarketStream => {
            "MarketStream[Union[StreamEvent[MarketEvent], StreamError]]".to_owned()
        }
        ApiType::AccountStream => {
            "AccountStream[Union[StreamEvent[AccountEvent], StreamError]]".to_owned()
        }
        ApiType::Unit => "None".to_owned(),
    }
}

fn python_named_type(name: &str) -> &str {
    match name {
        "String" => "str",
        "Timestamp" => "int",
        _ => name,
    }
}

fn identifier_helpers(name: &str) -> &'static str {
    match name {
        "Exchange" => {
            r#"
    def display_name(self) -> str:
        return self.value.capitalize()
"#
        }
        "Feature" => {
            r#"
    def needs_credentials(self) -> bool:
        return self.value in {
            "balances",
            "open_orders",
            "account_stream",
            "trading",
            "positions",
            "margin",
            "funding_payments",
            "margin_config",
            "reduce_only_orders",
        }

    def is_derivatives_only(self) -> bool:
        return self.value in {
            "positions",
            "margin",
            "funding_rates",
            "funding_payments",
            "margin_config",
            "reduce_only_orders",
        }
"#
        }
        "MarketKind" => {
            r#"
    def is_derivative(self) -> bool:
        return self.value == "perpetual"
"#
        }
        "Side" => {
            r#"
    def flip(self) -> Side:
        return Side.SELL if self is Side.BUY else Side.BUY
"#
        }
        "Interval" => {
            r#"
    def as_secs(self) -> Optional[int]:
        unit = self.value.rstrip("0123456789")
        if unit == "month":
            return None
        count = int(self.value[len(unit):])
        return count * {
            "sec": 1,
            "min": 60,
            "hour": 3_600,
            "day": 86_400,
            "week": 604_800,
        }[unit]

    def advance(self, timestamp_ns: int, count: int) -> Optional[int]:
        if not _is_i64(timestamp_ns) or not _is_i64(count):
            return None

        seconds = self.as_secs()
        if seconds is not None:
            span = seconds * 1_000_000_000 * count
            if not _is_i64(span):
                return None
            result = timestamp_ns + span
            return result if _is_i64(result) else None

        if abs(count) > (1 << 32) - 1:
            return None

        whole_seconds, nanoseconds = divmod(timestamp_ns, 1_000_000_000)
        current = _UNIX_EPOCH + timedelta(seconds=whole_seconds)
        month_index = current.year * 12 + current.month - 1 + count
        year, zero_based_month = divmod(month_index, 12)
        month = zero_based_month + 1
        if not 1 <= year <= 9999:
            return None

        moved = datetime(
            year,
            month,
            min(current.day, monthrange(year, month)[1]),
            current.hour,
            current.minute,
            current.second,
            tzinfo=timezone.utc,
        )
        elapsed = moved - _UNIX_EPOCH
        result = (
            (elapsed.days * 86_400 + elapsed.seconds) * 1_000_000_000
            + nanoseconds
        )
        return result if _is_i64(result) else None
"#
        }
        "OrderStatus" => {
            r#"
    def is_live(self) -> bool:
        return self.value in {"accepted", "open", "partially_filled"}
"#
        }
        "ExchangeErrorKind" => {
            r#"
    def is_retryable(self) -> bool:
        return self.value in {"rate_limited", "unavailable"}
"#
        }
        _ => "",
    }
}

pub(crate) fn snake_case(value: &str) -> String {
    let mut output = String::with_capacity(value.len());
    for character in value.chars() {
        if character.is_ascii_uppercase() {
            if !output.is_empty() {
                output.push('_');
            }
            output.push(character.to_ascii_lowercase());
        } else {
            output.push(character);
        }
    }
    output
}

fn items(values: &[&str]) -> String {
    values
        .iter()
        .map(|value| format!("\"{value}\""))
        .collect::<Vec<_>>()
        .join(", ")
}

fn owned_items(values: impl IntoIterator<Item = String>) -> String {
    values
        .into_iter()
        .map(|value| format!("\"{value}\""))
        .collect::<Vec<_>>()
        .join(", ")
}

fn render_provider(provider: &Provider) -> String {
    format!(
        "    \"{}\": ({},),\n",
        provider.exchange,
        items(
            &provider
                .methods
                .iter()
                .map(|method| method.rust_name)
                .collect::<Vec<_>>()
        ),
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use maxt_bindings_common::schema::binding_schema;

    #[test]
    fn generated_identifiers_cover_closed_and_open_enums() {
        let output = render_identifiers(&binding_schema());

        assert!(output.contains("class Exchange(str, Enum):\n    UPBIT = \"upbit\""));
        assert!(output.contains("class OrderStatus(str, Enum):"));
        assert!(output.contains("class HyperliquidLedgerKind(str, Enum):"));
        assert!(output.contains("def other(cls, value: str) -> HyperliquidLedgerKind:"));
        assert!(output.contains("def _missing_(cls, value: object) -> HyperliquidLedgerKind:"));
        assert!(output.contains("cls._value2member_map_[value] = member"));
        assert!(output.contains("class ExchangeErrorKind(str, Enum):"));
        assert!(output.contains("Exchange.__module__ = \"maxt.models\""));
        assert!(output.contains("ExchangeErrorKind.__module__ = \"maxt._api\""));
    }

    #[test]
    fn generated_public_api_covers_adapter_and_client_methods() {
        let schema = binding_schema();
        let output = render_api(&schema);

        for operation in schema.adapter_operations {
            assert!(
                output.contains(&format!("async def {}(", operation.rust_name)),
                "missing adapter operation {}",
                operation.rust_name
            );
            for method in operation.client_methods {
                assert!(
                    output.contains(&format!("async def {}(", snake_case(method.name))),
                    "missing client method {}",
                    method.name
                );
            }
        }
    }

    #[test]
    fn native_stub_uses_native_boundary_signatures() {
        let output = render_native_stub(&binding_schema());

        assert!(output.contains("def subscribe(self, subscription: Any, config: Any)"));
        assert!(output.contains("def order_books(self, markets: list[Any]"));
        assert!(output.contains("def region(self) -> str"));
        assert!(output.contains("from_ns: Optional[int]"));
        assert!(output.contains("to_ns: Optional[int]"));
    }

    #[test]
    fn rust_client_facade_covers_schema_methods_and_conversions() {
        let schema = binding_schema();
        let output = render_rust_client(&schema);

        for operation in schema.adapter_operations {
            for method in operation.client_methods {
                assert!(
                    output.contains(&format!("fn {}<'py>(", snake_case(method.name))),
                    "missing Rust façade method {}",
                    method.name
                );
            }
        }
        assert!(output.contains("core.subscribe_with(&subscription, &config).await"));
        assert!(output.contains("core.open_orders_on(&market).await"));
        assert!(output.contains("funding_rates_page_to_wire(py, &value)"));
    }

    #[test]
    fn generated_delegate_and_dispatcher_cover_every_operation() {
        let schema = binding_schema();
        let delegate = render_native_delegate(&schema);
        let dispatcher = render_rust_dispatcher(&schema);

        for operation in schema.adapter_operations {
            assert!(delegate.contains(&format!("async def {}(", operation.rust_name)));
            assert!(dispatcher.contains(&format!(
                "AdapterCall::{}",
                pascal_case(operation.rust_name)
            )));
        }
        assert!(delegate.contains("if not subscription.markets:"));
        assert!(delegate.contains("if not subscription.feeds:"));
    }

    #[test]
    fn generated_wire_schema_covers_structural_types() {
        let output = render_wire_schema(&binding_schema());

        assert!(output.contains("\"Market\": {"));
        assert!(output.contains("\"bids\": \"list:named:Level\""));
        assert!(output.contains("\"price\": \"optional:decimal\""));
        assert!(output.contains("\"Error\": {"));
        assert!(output.contains("\"exchange_kind\": \"string\""));
        assert!(output.contains("IDENTIFIER_VARIANTS"));
    }

    #[test]
    fn rust_convert_is_derived_from_identifiers_records_and_pages() {
        let output = render_rust_convert(&binding_schema());

        assert!(output.contains("maxt::Exchange::Upbit => Ok(\"upbit\")"));
        assert!(output.contains("pub(crate) fn order_book_to_wire"));
        assert!(output.contains("\"kind\" => market_kind_to_wire(value.kind)?"));
        assert!(output.contains("\"bids\" => list_to_wire(py, &value.bids, level_to_wire)?"));
        assert!(output.contains("value.price.map(decimal_to_wire)"));
        assert!(output.contains("pub(crate) fn funding_rates_page_to_wire"));
        assert!(output.contains("pub(crate) fn funding_payments_page_to_wire"));
        assert!(output.contains("maxt::Error::Exchange"));
        assert!(output.contains("\"provider_message\" => provider_message"));
    }

    #[test]
    fn rust_provider_convert_covers_provider_result_shapes() {
        let output = render_rust_provider_convert(&binding_schema());

        assert!(output.contains("fn upbit_market_event_to_wire"));
        assert!(output.contains("fn bithumb_market_warning_to_wire"));
        assert!(output.contains("fn binance_symbol_filters_to_wire"));
        assert!(output.contains("fn hyperliquid_ledger_page_to_wire"));
        assert!(output.contains("hyperliquid_ledger_kind_to_wire(&value.kind)?"));
    }
}
